const body = $json.body || $json;
const isToolCall = !!(body.tool && body.tool.name);
return [{ json: { _isToolCall: isToolCall, _raw: body } }];

const raw = $json._raw;
const call = raw.call || raw;
const artifact = raw.artifact || {};
const analysis = raw.analysis || {};
const meta = (call.assistantOverrides && call.assistantOverrides.metadata) || call.metadata || {};
const contactId = String(meta.contact_id || '').trim();
const queueId = String(meta.queue_id || '').trim();
const status = String(call.status || raw.status || '').toLowerCase();
const endedReason = String(call.endedReason || '').toLowerCase();
const successEvaluation = !!analysis.successEvaluation;
const summary = String(analysis.summary || artifact.summary || '').trim();
const recordingUrl = artifact.recordingUrl || call.recordingUrl || '';
let disposition = 'failed';
if (status.includes('ended') || status.includes('completed')) {
  if (endedReason.includes('customer-did-not-answer') || endedReason.includes('no-answer')) disposition = 'no_answer';
  else if (endedReason.includes('voicemail')) disposition = 'voicemail';
  else disposition = successEvaluation ? 'qualified_booked' : 'connected';
}
return [{ json: { contact_id: contactId, queue_id: queueId, call_id: String(call.id || raw.id || ''), disposition, summary: summary || 'No summary returned by Vapi.', recording_url: recordingUrl } }];

const raw = $json._raw;
const tool = raw.tool || {};
const params = tool.parameters || {};
const meta = raw.metadata || {};
const toolName = String(tool.name || '').toLowerCase();
const contactId = String(params.ghl_contact_id || params.contact_id || meta.contact_id || '').trim();
const queueId = String(meta.queue_id || params.queue_id || '').trim();
const callId = String(meta.call_id || params.call_id || '').trim();
const s = (v) => String(v ?? '').replace(/'/g, "''").trim();
return [{ json: { tool_name: toolName, tool_call_id: String(raw.toolCallId || raw.tool_call_id || tool.toolCallId || tool.tool_call_id || meta.tool_call_id || '').trim(), contact_id: contactId, queue_id: queueId, call_id: callId, route_update: toolName === 'update_lead_status', route_dnc: toolName === 'add_to_dnc', route_log: toolName === 'log_call_outcome', route_notify: toolName === 'notify_sales', route_referral: toolName === 'report_referral', disposition: s(params.disposition || ''), notes: s(params.notes || ''), follow_up_at: params.followUpAt || params.follow_up_at || null, reason: s(params.reason || ''), lead_name: s(params.lead_name || params.leadName || ''), company: s(params.company || ''), referral_name: s(params.referral_name || params.full_name || params.name || ''), referral_phone: s(params.referral_phone || params.phone || ''), referral_email: s(params.referral_email || params.email || ''), referral_role: s(params.referral_role || params.role || params.title || ''), referral_company: s(params.referral_company || params.company_name || params.company || ''), referrer_name: s(params.referrer_name || params.referrer || params.referred_by || '') } }];

const raw = $json;
const referralName = String(raw.referral_name || '').trim();
const referralPhone = String(raw.referral_phone || '').replace(/\D/g, '').trim();
const referralEmail = String(raw.referral_email || '').trim().toLowerCase();
const referralRole = String(raw.referral_role || '').trim();
const referralCompany = String(raw.referral_company || '').trim();
const referrerName = String(raw.referrer_name || '').trim();
const lookupType = referralEmail ? 'email' : referralPhone ? 'phone' : referralName ? 'name' : 'none';
const lookupValue = referralEmail || referralPhone || referralName || '';
return [{ json: { ...raw, referral_name: referralName, referral_phone: referralPhone, referral_email: referralEmail, referral_role: referralRole, referral_company: referralCompany, referrer_name: referrerName, referral_lookup_type: lookupType, referral_lookup_value: lookupValue, referral_lookup_status: lookupType === 'none' ? 'no_lookup_key' : 'pending', referral_found: false, referral_contact_id: '', referral_match_method: '', referral_contact_name: '', referral_contact_email: '', referral_contact_phone: '', referral_contact_company: '' } }];

const locationId = String($env.GHL_LOCATION_ID || 'Zwz4relUXVPxx8uohnjV').trim();
const apiBaseUrl = String($env.GHL_API_BASE_URL || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = String($env.GHL_API_KEY || '').trim();
const referralName = String($json.referral_name || '').trim();
const referralPhone = String($json.referral_phone || '').trim();
const referralEmail = String($json.referral_email || '').trim().toLowerCase();
const lookupType = String($json.referral_lookup_type || 'none');
const headers = { Authorization: `Bearer ${apiKey}`, Version: '2021-07-28', 'Content-Type': 'application/json', Accept: 'application/json' };

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest(method, path, body) {
  const options = { method, url: `${apiBaseUrl}${path}`, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return { ok: false, data: err?.response?.body || err?.message || err };
  }
}

function clean(v) { return String(v ?? '').trim(); }
function normalizeSpace(v) { return String(v || '').trim().replace(/\s+/g, ' '); }
function asContacts(payload) {
  if (Array.isArray(payload?.contacts)) return payload.contacts;
  if (Array.isArray(payload?.data?.contacts)) return payload.data.contacts;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload)) return payload;
  return [];
}

let referralFound = false;
let referralContactId = '';
let referralMatchMethod = '';
let referralContactName = '';
let referralContactEmail = '';
let referralContactPhone = '';
let referralContactCompany = '';
let referralLookupStatus = 'not_found';

if (lookupType === 'email') {
  const dup = await apiRequest.call(this, 'GET', `/contacts/search/duplicate?locationId=${encodeURIComponent(locationId)}&email=${encodeURIComponent(referralEmail)}`);
  if (dup.ok && dup.data?.contact?.id) {
    referralFound = true;
    referralContactId = clean(dup.data.contact.id);
    referralMatchMethod = 'email_duplicate';
    referralLookupStatus = 'found';
  } else if (!dup.ok) {
    referralLookupStatus = 'lookup_error';
  }
}

if (!referralFound && lookupType === 'phone') {
  const dup = await apiRequest.call(this, 'GET', `/contacts/search/duplicate?locationId=${encodeURIComponent(locationId)}&number=${encodeURIComponent(referralPhone)}`);
  if (dup.ok && dup.data?.contact?.id) {
    referralFound = true;
    referralContactId = clean(dup.data.contact.id);
    referralMatchMethod = 'phone_duplicate';
    referralLookupStatus = 'found';
  } else if (!dup.ok) {
    referralLookupStatus = 'lookup_error';
  }
}

if (!referralFound && lookupType === 'name' && referralName) {
  const byName = await apiRequest.call(this, 'GET', `/contacts/?locationId=${encodeURIComponent(locationId)}&query=${encodeURIComponent(referralName)}&limit=50`);
  if (byName.ok) {
    const contacts = asContacts(byName.data);
    const target = normalizeSpace(referralName).toLowerCase();
    const exact = contacts.find((c) => {
      const fn = normalizeSpace(`${c.firstName || ''} ${c.lastName || ''}`).toLowerCase();
      const nm = normalizeSpace(c.name || '').toLowerCase();
      return fn === target || nm === target;
    });
    if (exact?.id) {
      referralFound = true;
      referralContactId = clean(exact.id);
      referralMatchMethod = 'full_name';
      referralLookupStatus = 'found';
      referralContactName = normalizeSpace(`${exact.firstName || ''} ${exact.lastName || ''}`) || normalizeSpace(exact.name || '');
      referralContactEmail = clean(exact.email || '');
      referralContactPhone = clean(exact.phone || '');
      referralContactCompany = clean(exact.companyName || exact.company_name || exact.company || '');
    }
  } else {
    referralLookupStatus = 'lookup_error';
  }
}

if (referralFound && referralContactId && (!referralContactName || !referralContactEmail || !referralContactPhone || !referralContactCompany)) {
  const detail = await apiRequest.call(this, 'GET', `/contacts/${encodeURIComponent(referralContactId)}`);
  if (detail.ok) {
    const contact = detail.data?.contact || detail.data || {};
    referralContactName = referralContactName || normalizeSpace(`${contact.firstName || ''} ${contact.lastName || ''}`) || clean(contact.name || '');
    referralContactEmail = referralContactEmail || clean(contact.email || '');
    referralContactPhone = referralContactPhone || clean(contact.phone || '');
    referralContactCompany = referralContactCompany || clean(contact.companyName || contact.company_name || contact.company || '');
  }
}

return [{ json: { ...$json, referral_found: referralFound, referral_contact_id: referralContactId, referral_match_method: referralMatchMethod, referral_contact_name: referralContactName, referral_contact_email: referralContactEmail, referral_contact_phone: referralContactPhone, referral_contact_company: referralContactCompany, referral_lookup_status: referralLookupStatus } }];
